    if (JSON.stringify(storedValues) !== JSON.stringify(stored)) {
        store.set(DESKTOP_CONFIG_STORE_KEY, { ...storedValues, agentSelection });
    }

    return { ...resolved, agentProfiles, agentSelection };
}

